import { requestComputerActionTurn } from "@katalon-experiments/ai-client/agents";
import { requestProvider } from "./provider.mjs";

export function hasPendingComputerSafetyCheck(item) {
  return (
    item?.type === "computer_call" &&
    Boolean(item.pending_safety_checks?.length)
  );
}

export function requestBrowserAction(options) {
  return requestComputerActionTurn({
    request: options.request,
    signal: options.signal,
    dispatch: () => requestProvider(options),
    isTerminal: (output) => output.some(hasPendingComputerSafetyCheck),
  });
}
